namespace grass {
double clockMs(){return std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now().time_since_epoch()).count();}
static const Quad unit={Point(0,0),Point(1,0),Point(1,1),Point(0,1)};
static bool solve(std::vector<std::vector<double>> A,std::vector<double>b,std::vector<double>&out){int n=b.size();for(int i=0;i<n;i++)A[i].push_back(b[i]);for(int j=0;j<n;j++){int k=j;for(int i=j+1;i<n;i++)if(std::abs(A[i][j])>std::abs(A[k][j]))k=i;std::swap(A[j],A[k]);if(std::abs(A[j][j])<1e-12)return false;double d=A[j][j];for(int t=j;t<=n;t++)A[j][t]/=d;for(int i=0;i<n;i++)if(i!=j){double f=A[i][j];if(f)for(int t=j;t<=n;t++)A[i][t]-=f*A[j][t];}}out.resize(n);for(int i=0;i<n;i++)out[i]=A[i][n];return true;}
bool homography(const std::vector<Point>&s,const std::vector<Point>&d,H3&H){std::vector<std::vector<double>>N(8,std::vector<double>(8));std::vector<double>r(8),o;for(size_t i=0;i<s.size();i++){double x=s[i].x,y=s[i].y,u=d[i].x,v=d[i].y;double rows[2][9]={{x,y,1,0,0,0,-u*x,-u*y,u},{0,0,0,x,y,1,-v*x,-v*y,v}};for(auto&q:rows)for(int a=0;a<8;a++){r[a]+=q[a]*q[8];for(int b=0;b<8;b++)N[a][b]+=q[a]*q[b];}}if(!solve(N,r,o))return false;std::copy(o.begin(),o.end(),H.begin());H[8]=1;return true;}
Point applyH(const H3&H,double x,double y){double d=H[6]*x+H[7]*y+H[8];return {(H[0]*x+H[1]*y+H[2])/d,(H[3]*x+H[4]*y+H[5])/d};}
bool inv3(const H3&m,H3&o){double a=m[0],b=m[1],c=m[2],d=m[3],e=m[4],f=m[5],g=m[6],h=m[7],i=m[8],A=e*i-f*h,B=-(d*i-f*g),C=d*h-e*g,det=a*A+b*B+c*C;if(std::abs(det)<1e-18)return false;o={A/det,-(b*i-c*h)/det,(b*f-c*e)/det,B/det,(a*i-c*g)/det,-(a*f-c*d)/det,C/det,-(a*h-b*g)/det,(a*e-b*d)/det};return true;}
static H3 mul3(const H3&a,const H3&b){H3 o{};for(int i=0;i<3;i++)for(int j=0;j<3;j++)for(int k=0;k<3;k++)o[i*3+j]+=a[i*3+k]*b[k*3+j];return o;}
static double dist(Point a,Point b){return std::hypot(a.x-b.x,a.y-b.y);}
static double minSide(const Quad&q){double m=INFINITY;for(int i=0;i<4;i++)m=std::min(m,dist(q[i],q[(i+1)%4]));return m;}
static bool convex(const Quad&q){int s=0;for(int i=0;i<4;i++){Point a=q[i],b=q[(i+1)%4],c=q[(i+2)%4];double z=(b.x-a.x)*(c.y-b.y)-(b.y-a.y)*(c.x-b.x);if(!z)return false;int v=z>0?1:-1;if(!s)s=v;else if(s!=v)return false;}return true;}
static bool inImage(const Quad&q,int w,int h){for(auto p:q)if(!std::isfinite(p.x)||!std::isfinite(p.y)||p.x<0||p.y<0||p.x>=w-1||p.y>=h-1)return false;return true;}
static Quad gridQuad(const H3&H,int x,int z){Quad q;for(int i=0;i<4;i++)q[i]=applyH(H,x+unit[i].x,z+unit[i].y);return q;}
static double corr(const std::vector<double>&a,const std::vector<double>&b){double sa=0,sb=0,aa=0,bb=0,ab=0,n=a.size();for(size_t i=0;i<a.size();i++){sa+=a[i];sb+=b[i];aa+=a[i]*a[i];bb+=b[i]*b[i];ab+=a[i]*b[i];}double va=aa-sa*sa/n,vb=bb-sb*sb/n;if(va<1e-9||vb<1e-9)return 0;return (ab-sa*sb/n)/std::sqrt(va*vb);}
Verdict classify(const Context&c,const Quad&q){H3 H;std::vector<Point>s={{0,0},{16,0},{16,16},{0,16}},d(q.begin(),q.end());if(!homography(s,d,H))return {};float patch[256];const uint8_t*g=c.g.data();for(int j=0;j<16;j++)for(int i=0;i<16;i++){Point p=applyH(H,i+.5,j+.5);if(!(p.x>=0&&p.y>=0&&p.x<c.w-1&&p.y<c.h-1))return {};int xx=std::floor(p.x),yy=std::floor(p.y);double fx=p.x-xx,fy=p.y-yy;patch[j*16+i]=g[yy*c.w+xx]*(1-fx)*(1-fy)+g[yy*c.w+xx+1]*fx*(1-fy)+g[(yy+1)*c.w+xx]*(1-fx)*fy+g[(yy+1)*c.w+xx+1]*fx*fy;}
 std::vector<int>inner,quads[4];for(int j=1;j<15;j++)for(int i=1;i<15;i++){inner.push_back(j*16+i);quads[(i>=8?1:0)+(j>=8?2:0)].push_back(j*16+i);}auto scores=[&](const std::vector<int>&ids){std::array<double,4>sc;for(int k=0;k<4;k++){std::vector<double>a,b;for(int i:ids){a.push_back(patch[i]);b.push_back(c.refs[k][i]);}sc[k]=corr(a,b);}return sc;};auto sc=scores(inner);std::array<int,4>order={0,1,2,3};std::stable_sort(order.begin(),order.end(),[&](int a,int b){return sc[a]>sc[b];});int k=order[0],votes=0;for(auto&ids:quads){auto ss=scores(ids);int best=0;for(int a=1;a<4;a++)if(ss[a]>ss[best])best=a;if(best==k)votes++;}return {true,k,votes,sc[k],sc[k]-sc[order[1]]};}
// Batch verification deliberately uses the existing Float32 ABI and closed-form
// kernel; single/ECC verification uses the double precision reference above.
extern "C" {void set_refs(const unsigned char*);void classify_batch(const unsigned char*,int,int,const float*,int,float*);}
std::vector<Verdict> classifyBatchNative(const Context&c,const std::vector<Quad>&qs){std::vector<unsigned char>refs(1024);for(int k=0;k<4;k++)for(int i=0;i<256;i++)refs[k*256+i]=c.refs[k][i];set_refs(refs.data());std::vector<float>flat(qs.size()*8),out(qs.size()*5);for(size_t j=0;j<qs.size();j++)for(int i=0;i<4;i++){flat[j*8+i*2]=qs[j][i].x;flat[j*8+i*2+1]=qs[j][i].y;}classify_batch(c.g.data(),c.w,c.h,flat.data(),qs.size(),out.data());std::vector<Verdict>r(qs.size());for(size_t i=0;i<qs.size();i++)r[i]={out[i*5]!=0,int(out[i*5+1]),int(out[i*5+4]),out[i*5+2],out[i*5+3]};return r;}
class ECC {cv::Mat img;std::array<cv::Mat,4>targets;public:ECC(const Context&c):img(c.h,c.w,CV_32F){for(size_t i=0;i<c.g.size();i++)img.ptr<float>()[i]=c.g[i]/255.0f;for(int k=0;k<4;k++){targets[k]=cv::Mat(128,128,CV_32F);for(int y=0;y<128;y++)for(int x=0;x<128;x++)targets[k].at<float>(y,x)=c.refs[k][(y>>3)*16+(x>>3)]/255.;}}
bool operator()(const Quad&q,int rot,Quad&nq){std::vector<Point>s={{0,0},{128,0},{128,128},{0,128}},d(q.begin(),q.end());H3 base,bi;if(!homography(s,d,base)||!inv3(base,bi))return false;try{cv::Mat M(3,3,CV_64F,bi.data()),warped,W=cv::Mat::eye(3,3,CV_32F);cv::warpPerspective(img,warped,M,cv::Size(128,128),cv::INTER_LINEAR,cv::BORDER_REPLICATE);cv::findTransformECC(targets[rot],warped,W,cv::MOTION_HOMOGRAPHY,cv::TermCriteria(cv::TermCriteria::COUNT|cv::TermCriteria::EPS,60,1e-5),cv::noArray(),3);H3 wh;for(int i=0;i<9;i++)wh[i]=W.ptr<float>()[i];H3 full=mul3(base,wh);for(int i=0;i<4;i++)nq[i]=applyH(full,s[i].x,s[i].y);return true;}catch(const cv::Exception&){return false;}}};
static Block verify(const Context&c,Quad q,const Refiner&refine,Verdict r,bool supplied=false){if(!supplied)r=classify(c,q);Block b;if(!r.valid)return b;auto&t=c.opts;double rmin=std::isnan(t.refineMin)?t.relaxed:t.refineMin,rmargin=std::isnan(t.refineMargin)?t.margin:t.refineMargin;if(refine&&r.score>=rmin&&r.margin>=rmargin&&r.votes>=t.refineVotes){Quad nq;if(refine(q,r.rotation,nq)&&convex(nq)&&inImage(nq,c.w,c.h)){double shift=0;for(int i=0;i<4;i++)shift=std::max(shift,dist(nq[i],q[i]));if(shift<t.refineShift){auto r2=classify(c,nq);if(r2.valid&&r2.score>r.score){q=nq;r=r2;}}}}static_cast<Verdict&>(b)=r;b.quad=q;return b;}
static Plane planeFromSeeds(const std::vector<Block>&seeds){Plane best;std::vector<Point>u(unit.begin(),unit.end());for(auto&s:seeds){H3 H0,I;if(!homography(u,std::vector<Point>(s.quad.begin(),s.quad.end()),H0)||!inv3(H0,I))continue;std::vector<int>ids;std::vector<Point>src,dst;for(size_t k=0;k<seeds.size();k++){Quad loc;for(int i=0;i<4;i++)loc[i]=applyH(I,seeds[k].quad[i].x,seeds[k].quad[i].y);double ox=std::floor(loc[0].x+.5),oz=std::floor(loc[0].y+.5),err=0;for(int i=0;i<4;i++)err=std::max(err,dist(loc[i],unit[i]+Point(ox,oz)));if(err<.2){ids.push_back(k);for(int i=0;i<4;i++){src.push_back(unit[i]+Point(ox,oz));dst.push_back(seeds[k].quad[i]);}}}H3 H;if(src.size()>=4&&homography(src,dst,H)&&(!best.valid||ids.size()>best.ids.size()))best={true,H,ids};}return best;}
static std::vector<Block>growPlane(const Context&c,const H3&H,const Refiner&r,int range){std::vector<Block>cand,out;std::vector<Quad>qs;for(int z=-range;z<=range;z++)for(int x=-range;x<=range;x++){Quad q=gridQuad(H,x,z);if(!inImage(q,c.w,c.h)||!convex(q)||minSide(q)<12)continue;Block b;b.quad=q;b.x=x;b.z=z;cand.push_back(b);qs.push_back(q);}auto vs=classifyBatchNative(c,qs);for(size_t i=0;i<cand.size();i++){auto b=verify(c,cand[i].quad,r,vs[i],true);if(b.valid&&b.score>=c.opts.accept&&b.margin>=c.opts.margin&&b.votes==4){b.x=cand[i].x;b.z=cand[i].z;out.push_back(b);}}return out;}
static bool cameraFromPlane(const H3&H,int w,int h,Camera&P,double&f){double cx=w/2.,cy=h/2.,v1x=H[0]/H[6],v1y=H[3]/H[6],v2x=H[1]/H[7],v2y=H[4]/H[7];if(!std::isfinite(v1x+v1y+v2x+v2y))return false;double f2=-((v1x-cx)*(v2x-cx)+(v1y-cy)*(v2y-cy));if(!(f2>100))return false;f=std::sqrt(f2);std::array<double,3>a={(H[0]-cx*H[6])/f,(H[3]-cy*H[6])/f,H[6]},c={(H[1]-cx*H[7])/f,(H[4]-cy*H[7])/f,H[7]},b={c[1]*a[2]-c[2]*a[1],c[2]*a[0]-c[0]*a[2],c[0]*a[1]-c[1]*a[0]};auto norm=[](auto a){return std::hypot(a[0],a[1],a[2]);};double s=(norm(a)+norm(c))/2/norm(b);for(double&v:b)v*=s;P={H[0],f*b[0]+cx*b[2],H[1],H[2],H[3],f*b[1]+cy*b[2],H[4],H[5],H[6],b[2],H[7],H[8]};if((P[7]+P[5])/(P[11]+P[9])>P[7]/P[11])for(int i:{1,5,9})P[i]=-P[i];return true;}
static bool projectQuad(const Camera&P,int x,int y,int z,int w,int h,Quad&q){for(int i=0;i<4;i++){double X=x+unit[i].x,Z=z+unit[i].y,d=P[8]*X+P[9]*y+P[10]*Z+P[11];if(d<=0)return false;double u=(P[0]*X+P[1]*y+P[2]*Z+P[3])/d;if(!(u>=0&&u<w-1))return false;double v=(P[4]*X+P[5]*y+P[6]*Z+P[7])/d;if(!(v>=0&&v<h-1))return false;q[i]={u,v};}if(!convex(q))return false;for(int i=0;i<4;i++){Point d=q[i]-q[(i+1)%4];if(d.x*d.x+d.y*d.y<64)return false;}return true;}
static void jacobi(std::vector<std::vector<double>> A,int n,std::vector<double>&vals,std::vector<std::vector<double>>&V){V.assign(n,std::vector<double>(n));for(int i=0;i<n;i++)V[i][i]=1;for(int sweep=0;sweep<60;sweep++){double off=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)off+=A[i][j]*A[i][j];if(off<1e-24)break;for(int p=0;p<n;p++)for(int q=p+1;q<n;q++){if(std::abs(A[p][q])<1e-30)continue;double th=(A[q][q]-A[p][p])/(2*A[p][q]),t=(th<0?-1.:1.)/(std::abs(th)+std::sqrt(th*th+1)),c=1/std::sqrt(t*t+1),s=t*c;for(int k=0;k<n;k++){double ap=A[k][p],aq=A[k][q];A[k][p]=c*ap-s*aq;A[k][q]=s*ap+c*aq;}for(int k=0;k<n;k++){double ap=A[p][k],aq=A[q][k];A[p][k]=c*ap-s*aq;A[q][k]=s*ap+c*aq;}for(int k=0;k<n;k++){double vp=V[k][p],vq=V[k][q];V[k][p]=c*vp-s*vq;V[k][q]=s*vp+c*vq;}}}vals.resize(n);for(int i=0;i<n;i++)vals[i]=A[i][i];}
static bool dlt(const std::vector<std::array<double,3>>&pts,const std::vector<Point>&pix,Camera&out){double n=pts.size();std::array<double,3>c3{};Point c2{};for(auto p:pts)for(int i=0;i<3;i++)c3[i]+=p[i]/n;for(auto p:pix){c2.x+=p.x/n;c2.y+=p.y/n;}double d3=0,d2=0;for(auto p:pts)d3+=std::hypot(p[0]-c3[0],p[1]-c3[1],p[2]-c3[2])/n;for(auto p:pix)d2+=dist(p,c2)/n;double s3=std::sqrt(3)/(d3?d3:1),s2=std::sqrt(2)/(d2?d2:1);std::vector<std::vector<double>>S(12,std::vector<double>(12));for(size_t i=0;i<pts.size();i++){std::array<double,4>v={(pts[i][0]-c3[0])*s3,(pts[i][1]-c3[1])*s3,(pts[i][2]-c3[2])*s3,1};double u=(pix[i].x-c2.x)*s2,w=(pix[i].y-c2.y)*s2;std::array<double,12>r1{},r2{};for(int k=0;k<4;k++){r1[k]=v[k];r1[k+8]=-u*v[k];r2[k+4]=v[k];r2[k+8]=-w*v[k];}for(auto&r:{r1,r2})for(int a=0;a<12;a++)for(int b=0;b<12;b++)S[a][b]+=r[a]*r[b];}std::vector<double>vals;std::vector<std::vector<double>>vecs;jacobi(S,12,vals,vecs);int mi=0;for(int i=0;i<12;i++)if(vals[i]<vals[mi])mi=i;Camera pn;for(int i=0;i<12;i++)pn[i]=vecs[i][mi];double T3[4][4]={{s3,0,0,-s3*c3[0]},{0,s3,0,-s3*c3[1]},{0,0,s3,-s3*c3[2]},{0,0,0,1}},T2i[3][3]={{1/s2,0,c2.x},{0,1/s2,c2.y},{0,0,1}},tmp[3][4]{};for(int i=0;i<3;i++)for(int j=0;j<4;j++)for(int k=0;k<4;k++)tmp[i][j]+=pn[i*4+k]*T3[k][j];out.fill(0);for(int i=0;i<3;i++)for(int j=0;j<4;j++)for(int k=0;k<3;k++)out[i*4+j]+=T2i[i][k]*tmp[k][j];double sc=out[11];if(std::abs(sc)<1e-12)return false;for(double&v:out)v/=sc;return true;}
static double reproj(const Camera&P,const std::vector<std::array<double,3>>&pts,const std::vector<Point>&pix){double s=0;for(size_t i=0;i<pts.size();i++){auto a=pts[i];double w=P[8]*a[0]+P[9]*a[1]+P[10]*a[2]+P[11],u=(P[0]*a[0]+P[1]*a[1]+P[2]*a[2]+P[3])/w,v=(P[4]*a[0]+P[5]*a[1]+P[6]*a[2]+P[7])/w;s+=dist({u,v},pix[i]);}return s/pts.size();}
static std::vector<Block>voxel(const Context&c,const Plane&plane,const Refiner&r,Camera&bestP,bool&has){Camera P;double f;if(!cameraFromPlane(plane.H,c.w,c.h,P,f))return {};int prev=-1;std::vector<Block>best;has=false;for(int round=0;round<4;round++){std::vector<Block>cand,accept,kept;std::vector<Quad>qs;for(int y=-12;y<=12;y++)for(int z=-30;z<=30;z++)for(int x=-30;x<=30;x++){Quad q;if(!projectQuad(P,x,y,z,c.w,c.h,q))continue;Block b;b.quad=q;b.x=x;b.y=y;b.z=z;cand.push_back(b);qs.push_back(q);}auto vs=classifyBatchNative(c,qs);for(size_t i=0;i<cand.size();i++){auto b=verify(c,cand[i].quad,r,vs[i],true);if(b.valid&&b.score>c.opts.relaxed&&b.margin>c.opts.margin&&b.votes==4){b.x=cand[i].x;b.y=cand[i].y;b.z=cand[i].z;accept.push_back(b);}}std::stable_sort(accept.begin(),accept.end(),[](auto&a,auto&b){return a.score>b.score;});std::vector<Point>centers;std::vector<double>sides;for(auto&b:accept){Point center{};for(auto p:b.quad){center.x+=p.x/4;center.y+=p.y/4;}double sd=minSide(b.quad);bool overlap=false;for(size_t i=0;i<kept.size();i++)if(dist(centers[i],center)<.5*std::min(sd,sides[i])){overlap=true;break;}if(!overlap){kept.push_back(b);centers.push_back(center);sides.push_back(sd);}}std::set<int>heights;for(auto&b:kept)heights.insert(b.y);if(!has||kept.size()>best.size()){best=kept;bestP=P;has=true;}if(int(kept.size())<=prev||kept.size()<size_t(c.opts.refitFlat&&heights.size()==1?3:6))break;prev=kept.size();if(heights.size()==1){if(!c.opts.refitFlat)break;std::vector<Point>src,dst;for(auto&b:kept)for(int i=0;i<4;i++){src.push_back(unit[i]+Point(b.x,b.z));dst.push_back(b.quad[i]);}H3 H;Camera flat;if(!homography(src,dst,H)||!cameraFromPlane(H,c.w,c.h,flat,f))break;P=flat;for(int i:{0,4,8})P[i+3]-=P[i+1]*(*heights.begin());continue;}std::vector<std::array<double,3>>p3;std::vector<Point>pix;for(auto&b:kept)for(int i=0;i<4;i++){p3.push_back({b.x+unit[i].x,double(b.y),b.z+unit[i].y});pix.push_back(b.quad[i]);}Camera p2;if(!dlt(p3,pix,p2)||!(reproj(p2,p3,pix)<3))break;P=p2;}return best;}
static std::vector<Block>topDown(const Context&c){std::vector<double>periods;const uint8_t*g=c.g.data();for(int axis=0;axis<2;axis++){int n=axis?c.h:c.w,other=axis?c.w:c.h;std::vector<double>e(n-1);for(int j=0;j<other;j+=3)for(int i=0;i<n-1;i++){int p=axis?i*c.w+j:j*c.w+i;e[i]+=std::abs(int(g[p+(axis?c.w:1)])-int(g[p]));}double mean=std::accumulate(e.begin(),e.end(),0.)/e.size();std::vector<std::pair<double,double>>pk;for(int k=std::ceil(n/24.);k<n/2.;k++){double re=0,im=0,an=2*std::acos(-1)*k/e.size();for(size_t i=0;i<e.size();i++){double v=e[i]-mean;re+=v*std::cos(an*i);im+=v*std::sin(an*i);}pk.push_back({e.size()/double(k)*16,re*re+im*im});}std::stable_sort(pk.begin(),pk.end(),[](auto&a,auto&b){return a.second>b.second;});for(size_t i=0;i<std::min(size_t(2),pk.size());i++)periods.push_back(pk[i].first);}std::vector<int>sizes;for(double p:periods)for(int d:{-1,0,1}){int n=std::floor(p+.5)+d;if(n>=48&&n<std::min(c.w,c.h)*.6&&std::find(sizes.begin(),sizes.end(),n)==sizes.end())sizes.push_back(n);}Block best;for(int n:sizes){int st=std::max(2,n/32);for(int y=0;y<c.h-n;y+=st)for(int x=0;x<c.w-n;x+=st){Quad q={Point(x,y),Point(x+n,y),Point(x+n,y+n),Point(x,y+n)};auto r=classify(c,q);if(r.valid&&r.score>.72&&(!best.valid||r.score>best.score)){static_cast<Verdict&>(best)=r;best.quad=q;}}}return best.valid?std::vector<Block>{best}:std::vector<Block>{};}
Result runDetection(Context&c,const std::vector<Quad>&raw,bool manual,Timings&t){Result result;ECC ecc(c);Refiner refine=[&](const Quad&q,int rot,Quad&out){double start=clockMs();bool ok=ecc(q,rot,out);t.ecc+=clockMs()-start;return ok;};double start=clockMs();for(auto&q:raw){auto b=verify(c,q,refine,{});if(b.valid&&b.score>=c.opts.accept&&b.margin>=c.opts.margin&&b.votes==4)result.seeds.push_back(b);}if(result.seeds.empty()&&!manual){double fs=clockMs();auto seeds=topDown(c);t.latticeFallback+=clockMs()-fs;for(auto b:seeds)if(b.score>=c.opts.accept)result.seeds.push_back(b);}t.verify+=clockMs()-start;if(result.seeds.empty()){result.reason=manual?"your quad did not verify as a grass top (correlation too low). Make the corners tighter.":"no reliable grass tile found automatically. Draw one tile quad by hand.";return result;}start=clockMs();Plane plane=planeFromSeeds(result.seeds);if(!plane.valid){result.reason="seeds do not share a plane lattice";return result;}auto blocks=growPlane(c,plane.H,refine,28);result.mode="planar lattice (all y=0)";if(c.opts.refitPlane)for(int round=0;round<3&&blocks.size()>=3;round++){std::vector<Point>src,dst;for(auto&b:blocks)for(int i=0;i<4;i++){src.push_back(unit[i]+Point(b.x,b.z));dst.push_back(b.quad[i]);}H3 H;if(!homography(src,dst,H))break;auto next=growPlane(c,H,refine,28);if(next.size()<=blocks.size())break;blocks=next;plane.H=H;}t.plane+=clockMs()-start;start=clockMs();bool has=false;Camera cam;auto v=voxel(c,plane,refine,cam,has);if(has&&v.size()>=blocks.size()){blocks=v;result.camera=cam;result.hasCamera=true;std::set<int>heights;for(auto&b:blocks)heights.insert(b.y);result.mode="3D voxel lattice (heights ";for(int h:heights){if(result.mode.back()!=' ')result.mode+=",";result.mode+=std::to_string(h);}result.mode+=")";}t.voxel+=clockMs()-start;std::stable_sort(blocks.begin(),blocks.end(),[](auto&a,auto&b){return a.score>b.score;});result.blocks=blocks;result.planeH=plane.H;result.hasPlane=true;result.reason=blocks.empty()?"seed found but no neighbours verified":"";return result;}
std::vector<Block>mergeAligned(const std::vector<Block>&a,const std::vector<Block>&incoming){using Key=std::array<int,3>;std::vector<Key>evidence,order;std::map<Key,int>votes;for(auto&b:incoming){const Block*nearest=nullptr;double best=INFINITY;for(auto&o:a){double scale=minSide(o.quad),err=0;for(int i=0;i<4;i++)err+=dist(b.quad[i],o.quad[i]);err/=4;if(err<std::max(3.,scale*.12)&&err<best){best=err;nearest=&o;}}if(!nearest)continue;if(nearest->rotation!=b.rotation)return a;Key key={nearest->x-b.x,nearest->y-b.y,nearest->z-b.z};evidence.push_back(key);if(!votes.count(key))order.push_back(key);votes[key]++;}if(order.empty())return a;Key winner=order[0];for(auto key:order)if(votes[key]>votes[winner])winner=key;if(votes[winner]<3||votes[winner]<evidence.size()*.9)return a;auto merged=a;std::map<Key,int>coords;for(auto&b:a)coords[{b.x,b.y,b.z}]=b.rotation;for(auto&b:incoming){Key key={b.x+winner[0],b.y+winner[1],b.z+winner[2]};if(coords.count(key)&&coords[key]!=b.rotation)return a;}for(auto b:incoming){b.x+=winner[0];b.y+=winner[1];b.z+=winner[2];Key key={b.x,b.y,b.z};if(!coords.count(key)){merged.push_back(b);coords[key]=b.rotation;}}return merged;}
}
